def normalize(payload):
    return {'customer_id': int(payload['customer_id'])}

def save(record, rows):
    rows.append(dict(record))

def create_response(payload):
    rows = []
    record = normalize(payload)
    save(record, rows)
    return {'customer_id': str(rows[0]['customer_id'])}

