import durations as d
assert d.parse('1h30m') == 5400
assert d.parse('45s') == 45
assert d.parse('1h2m3s') == 3723
assert d.format(5400) == '1h30m'
assert d.format(0) == '0s'
assert d.format(3723) == '1h2m3s'
for bad in ['', '3x', '1m1h', '1h1h']:
    try:
        d.parse(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(bad)
try:
    d.format(-1)
except ValueError:
    pass
else:
    raise AssertionError('negative')

